const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  try {
    // 1. Geometry & Time Definitions (Toliara, Madagascar; ~15 km radius)
    const geom = ee.Geometry.Point([43.67, -23.35]).buffer(15000);
    const baselineYears = {start: 2000, end: 2015};  // inclusive
    const targetYears = {start: 2021, end: 2022};    // inclusive
    const month = 9; // September

    // Helpers
    function maskMOD13(img) {
      // Scale and QA
      const nd = img.select('NDVI').multiply(0.0001);
      const hasQA = img.bandNames().contains('SummaryQA');
      const qaMask = ee.Image(ee.Algorithms.If(hasQA, img.select('SummaryQA').lte(1), ee.Image(1)));
      const ndvi = nd.updateMask(qaMask).rename('ndvi');
      return ndvi.updateMask(ndvi.gte(-0.2).and(ndvi.lte(1)));
    }
    async function getPeriodImgMOD13(dataset, yrs) {
      const colRaw = ee.ImageCollection(dataset)
        .filterBounds(geom)
        .filter(ee.Filter.calendarRange(yrs.start, yrs.end, 'year'))
        .filter(ee.Filter.calendarRange(month, month, 'month'));
      const size = await colRaw.size().getInfo();
      if (size === 0) return {img: null, size: 0};
      const img = colRaw.map(maskMOD13).mean(); // single-band 'ndvi'
      return {img, size};
    }

    // 2. Data Acquisition & Check with fallback if needed
    let dataset = 'MODIS/061/MOD13Q1';
    let base = await getPeriodImgMOD13(dataset, baselineYears);
    let targ = await getPeriodImgMOD13(dataset, targetYears);

    if (base.size === 0 || targ.size === 0) {
      // Fallback to Aqua NDVI
      dataset = 'MODIS/061/MYD13Q1';
      base = await getPeriodImgMOD13(dataset, baselineYears);
      targ = await getPeriodImgMOD13(dataset, targetYears);
    }
    if (base.size === 0 || targ.size === 0) {
      console.log(`Dataset used: None (empty collections)`);
      console.log(`Baseline Sep ${baselineYears.start}-${baselineYears.end} Images: ${base.size}`);
      console.log(`Target Sep ${targetYears.start}-${targetYears.end} Images: ${targ.size}`);
      console.log('C1: Empty Collection (No images found in date/location for one or both comparison points).');
      console.log('C1');
      return;
    }

    // 3. Processing & Validation (counts)
    const scale = 1000;
    const totalPix = await ee.Image(1).reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: geom, scale: scale, maxPixels: 1e9
    }).get('constant').getInfo();

    const baseCount = await base.img.reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: geom, scale: scale, maxPixels: 1e9
    }).get('ndvi').getInfo() || 0;

    const targCount = await targ.img.reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: geom, scale: scale, maxPixels: 1e9
    }).get('ndvi').getInfo() || 0;

    if (baseCount === 0 || targCount === 0) {
      console.log(`Dataset used: ${dataset}`);
      console.log(`Baseline Sep ${baselineYears.start}-${baselineYears.end} Images: ${base.size}`);
      console.log(`Target Sep ${targetYears.start}-${targetYears.end} Images: ${targ.size}`);
      console.log(`Total pixels (@${scale} m): ${totalPix}`);
      console.log(`Baseline valid px: ${baseCount} (${(100*baseCount/totalPix).toFixed(1)}%)`);
      console.log(`Target valid px: ${targCount} (${(100*targCount/totalPix).toFixed(1)}%)`);
      console.log('C2: No Valid Pixels (Images exist, but after masking/processing, 0 pixels remain).');
      console.log('C2');
      return;
    }

    const baseMean = await base.img.reduceRegion({
      reducer: ee.Reducer.mean(),
      geometry: geom, scale: scale, maxPixels: 1e9
    }).get('ndvi').getInfo();

    const targMean = await targ.img.reduceRegion({
      reducer: ee.Reducer.mean(),
      geometry: geom, scale: scale, maxPixels: 1e9
    }).get('ndvi').getInfo();

    // 4. Calculation checks
    const invalid = (v) => (v === null || isNaN(v) || v < -0.2 || v > 1.0);
    if (invalid(baseMean) || invalid(targMean)) {
      console.log(`Dataset used: ${dataset}`);
      console.log(`Baseline Sep ${baselineYears.start}-${baselineYears.end} Images: ${base.size}`);
      console.log(`Target Sep ${targetYears.start}-${targetYears.end} Images: ${targ.size}`);
      console.log(`Baseline NDVI mean: ${baseMean}`);
      console.log(`Target NDVI mean: ${targMean}`);
      console.log('C3: Calculation Failure (Result is None/NaN/invalid).');
      console.log('C3');
      return;
    }

    // 5. Evidence & Final Answer
    const diff = targMean - baseMean;
    const pct = (diff / baseMean) * 100;
    console.log(`Dataset used: ${dataset}`);
    console.log(`Baseline Sep ${baselineYears.start}-${baselineYears.end} Images: ${base.size}`);
    console.log(`Target Sep ${targetYears.start}-${targetYears.end} Images: ${targ.size}`);
    console.log(`Total pixels (@${scale} m): ${totalPix}`);
    console.log(`Baseline valid px: ${baseCount} (${(100*baseCount/totalPix).toFixed(1)}%)`);
    console.log(`Target valid px: ${targCount} (${(100*targCount/totalPix).toFixed(1)}%)`);
    console.log(`Baseline NDVI mean: ${baseMean.toFixed(3)}`);
    console.log(`Target NDVI mean: ${targMean.toFixed(3)} (Δ=${diff.toFixed(3)}, ${pct.toFixed(1)}%)`);
    console.log(diff < 0 ? 'A: Yes' : 'B: No');
  } catch (err) {
    console.log(`Error: ${err}`);
    console.log('D');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
